diff --git a/source/core/utils/proxy-events-once.ts b/source/core/utils/proxy-events-once.ts
new file mode 100644
index 0000000..889824c
--- /dev/null
+++ b/source/core/utils/proxy-events-once.ts
@@ -0,0 +1,24 @@
+import type {EventEmitter} from 'node:events';
+
+type AnyFunction = (...arguments_: unknown[]) => void;
+type Functions = Record<string, AnyFunction>;
+
+export default function proxyEventsOnce(from: EventEmitter, to: EventEmitter, events: Readonly<string[]>): () => void {
+	const eventFunctions: Functions = {};
+
+	for (const event of events) {
+		const eventFunction = (...arguments_: unknown[]) => {
+			to.emit(event, ...arguments_);
+		};
+
+		eventFunctions[event] = eventFunction;
+
+		from.once(event, eventFunction);
+	}
+
+	return () => {
+		for (const [event, eventFunction] of Object.entries(eventFunctions)) {
+			from.off(event, eventFunction);
+		}
+	};
+}
diff --git a/test/proxy-events-once.ts b/test/proxy-events-once.ts
new file mode 100644
index 0000000..e02602f
--- /dev/null
+++ b/test/proxy-events-once.ts
@@ -0,0 +1,62 @@
+import {EventEmitter} from 'node:events';
+import test from 'ava';
+import proxyEventsOnce from '../source/core/utils/proxy-events-once.js';
+
+test('forwards each event at most once with its arguments', t => {
+	const from = new EventEmitter();
+	const to = new EventEmitter();
+	const calls: unknown[][] = [];
+
+	to.on('connect', (...arguments_: unknown[]) => {
+		calls.push(arguments_);
+	});
+
+	proxyEventsOnce(from, to, ['connect']);
+
+	from.emit('connect', 1, 'two');
+	from.emit('connect', 3);
+
+	t.deepEqual(calls, [[1, 'two']]);
+	t.is(from.listenerCount('connect'), 0);
+});
+
+test('forwards each named event independently', t => {
+	const from = new EventEmitter();
+	const to = new EventEmitter();
+	const received: string[] = [];
+
+	to.on('socket', () => received.push('socket'));
+	to.on('connect', () => received.push('connect'));
+
+	proxyEventsOnce(from, to, ['socket', 'connect']);
+
+	from.emit('socket');
+	from.emit('socket');
+	from.emit('connect');
+	from.emit('connect');
+
+	t.deepEqual(received, ['socket', 'connect']);
+});
+
+test('cleanup detaches listeners that have not fired yet', t => {
+	const from = new EventEmitter();
+	const to = new EventEmitter();
+	let count = 0;
+
+	to.on('connect', () => count++);
+
+	const cleanup = proxyEventsOnce(from, to, ['connect', 'secureConnect']);
+
+	from.emit('secureConnect');
+	cleanup();
+
+	t.is(from.listenerCount('connect'), 0);
+	t.is(from.listenerCount('secureConnect'), 0);
+
+	from.emit('connect');
+	t.is(count, 0);
+
+	t.notThrows(() => {
+		cleanup();
+	});
+});
